// Renames the disableTooltip input -> hideHint on attributes of <app-pill>, <app-fancy-pill>, <app-status-pill> start tags only.
const fs = require('fs'), path = require('path');
const root = process.argv[2];
const apply = process.argv.includes('--apply');
const TAG = /<(app-pill|app-fancy-pill|app-status-pill)(?=[\s\/>])/g;

function processStartTags(text) {
  let out = '', last = 0, count = 0, m;
  TAG.lastIndex = 0;
  while ((m = TAG.exec(text))) {
    const start = m.index + m[0].length;
    let i = start, q = null;
    while (i < text.length) {
      const c = text[i];
      if (q) { if (c === q) q = null; }
      else if (c === '"' || c === "'") q = c;
      else if (c === '>') break;
      i++;
    }
    const region = text.slice(start, i);
    const parts = region.split(/("[^"]*"|'[^']*')/);
    let newRegion = '';
    parts.forEach((p, idx) => {
      if (idx % 2 === 1) { newRegion += p; return; }
      newRegion += p.replace(/(^|\s)([\[(]?)disableTooltip([\])]?)(?=\s|=|\/|$)/g, (all, a, b, c) => { count++; return a + b + 'hideHint' + c; });
    });
    out += text.slice(last, start) + newRegion;
    last = i;
    TAG.lastIndex = i;
  }
  out += text.slice(last);
  return { text: out, count };
}

function walk(dir, acc) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (/\.(html|ts)$/.test(e.name)) acc.push(p);
  }
  return acc;
}

let total = 0;
for (const f of walk(root, [])) {
  const src = fs.readFileSync(f, 'utf8');
  const r = processStartTags(src);
  if (r.count) {
    total += r.count;
    console.log(r.count, path.relative(root, f));
    if (apply) fs.writeFileSync(f, r.text, 'utf8');
  }
}
console.log('TOTAL', total, apply ? '(applied)' : '(dry run)');
EOF
